def load_pdf_chunks(path, chunk_size=1000, overlap=200):
    chunks = []
    for page_num, page in enumerate(PdfReader(path).pages, start=1):
        text = (page.extract_text() or "").strip()
        start = 0
        while start < len(text):
            piece = text[start:start + chunk_size].strip()
            if piece:
                chunks.append({"page": page_num, "text": piece})
            start += chunk_size - overlap
    return chunks

def embed(texts, batch=32):
    vecs = []
    for i in range(0, len(texts), batch):
        vecs += ollama.embed(model=embed_model, input=texts[i:i + batch])["embeddings"]
    vecs = np.array(vecs, dtype=np.float32)
    return vecs / np.linalg.norm(vecs, axis=1, keepdims=True)

