from mcp.server.mcpserver import MCPServer

TICKET_CATEGORIES = {"Access", "Software", "Hardware", "Account"}
mcp_server = MCPServer("policy-assistant-tools")

def db():
    con = sqlite3.connect(DB_PATH)
    con.row_factory = sqlite3.Row
    return con

@mcp_server.tool()
def get_leave_balance(employee_id: int) -> dict:
    """Get the remaining annual leave balance and join date for one employee, e.g. employee_id=1005."""
    with db() as con:
        row = con.execute("SELECT id, name, leave_balance, join_date FROM employees WHERE id = ?",
                          (employee_id,)).fetchone()
    if row is None:
        return {"error": f"No employee found with id {employee_id}"}
    return {"employee_id": row["id"], "name": row["name"],
            "leave_balance_days": row["leave_balance"], "join_date": row["join_date"]}

@mcp_server.tool()
def calculate_working_days(start_date: str, end_date: str) -> dict:
    """Count working days between two dates (inclusive), excluding weekends and company holidays.
    Dates must be in YYYY-MM-DD format."""
    try:
        start, end = date.fromisoformat(start_date), date.fromisoformat(end_date)
    except ValueError:
        return {"error": "Dates must be in YYYY-MM-DD format"}
    if end < start:
        return {"error": "end_date is before start_date"}
    with db() as con:
        holidays = {r["date"]: r["name"] for r in con.execute(
            "SELECT date, name FROM holidays WHERE date BETWEEN ? AND ?", (start_date, end_date))}
    working, skipped, d = 0, [], start
    while d <= end:
        if d.weekday() < 5:
            if d.isoformat() in holidays:
                skipped.append(f"{d.isoformat()} ({holidays[d.isoformat()]})")
            else:
                working += 1
        d += timedelta(days=1)
    return {"start_date": start_date, "end_date": end_date,
            "working_days": working, "holidays_excluded": skipped}

@mcp_server.tool()
def create_it_ticket(employee_id: int, category: str, description: str) -> dict:
    """Create an IT service desk ticket. category must be one of: Access, Software, Hardware, Account.
    Only call this after the user's request has been approved."""
    category = category.strip().title()
    if category not in TICKET_CATEGORIES:
        return {"error": f"category must be one of {sorted(TICKET_CATEGORIES)}"}
    if not description.strip():
        return {"error": "description cannot be empty"}
    with db() as con:
        if not con.execute("SELECT 1 FROM employees WHERE id = ?", (employee_id,)).fetchone():
            return {"error": f"No employee found with id {employee_id}"}
        cur = con.execute("INSERT INTO tickets (employee_id, category, description) VALUES (?, ?, ?)",
                          (employee_id, category, description.strip()))
    return {"ticket_id": cur.lastrowid, "status": "open", "category": category}

@mcp_server.tool()
def search_policies(query: str, k: int = 3) -> dict:
    """Search the HR and IT policy documents and return the most relevant passages with their source."""
    res = col.query(query_embeddings=[embed([query])[0].tolist()], n_results=k)
    return {"results": [{"source": f"{m['source']} p.{m['page']}", "text": d}
                        for d, m in zip(res["documents"][0], res["metadatas"][0])]}

