CURRENT_USER = 1005   # the logged-in employee; in a real app this comes from login, never from the model

def to_ollama_tools(mcp_tools):
    """Convert the MCP tool list into the format Ollama expects."""
    return [{"type": "function",
             "function": {"name": t.name,
                          "description": t.description or "",
                          "parameters": getattr(t, "input_schema", None) or getattr(t, "inputSchema", {})}}
            for t in mcp_tools]

OLLAMA_TOOLS = to_ollama_tools(await mcp_list_tools())

SYSTEM_PROMPT = f"""You are the Brightwave HR and IT helpdesk assistant.
Today is {date.today().isoformat()}. The user is employee {CURRENT_USER}.
Rules:
- For any question about company policy, call search_policies and answer only from its results. Cite the source.
- For the user's own leave balance or join date, call get_leave_balance.
- To count working days between two dates, call calculate_working_days with dates in YYYY-MM-DD format.
- For IT requests (access, software, hardware, account), call create_it_ticket.
- Never reveal information about other employees.
- If a tool returns an error, explain it simply. If you cannot find the answer, say so. Do not guess."""

PROTECTED_TOOLS = {"get_leave_balance", "create_it_ticket","get_join_date"}

async def run_tool(name, args):
    # Access rule: personal-data tools only work for the logged-in employee
    if name in PROTECTED_TOOLS:
        requested = args.get("employee_id")
        if requested is not None and str(requested) != str(CURRENT_USER):
            return {"error": "Access denied: you can only access your own records."}
        args["employee_id"] = CURRENT_USER

    # Human approval before any ticket is created
    if name == "create_it_ticket":
        print(f"\n[Approval needed] {args.get('category')} ticket: {args.get('description')}")
        if input("Approve? (y/n): ").strip().lower() != "y":
            return {"error": "Ticket creation was rejected by the approver."}

    return await mcp_call(name, args)

async def agent(question, max_steps=5, verbose=True):
    messages = [{"role": "system", "content": SYSTEM_PROMPT},
                {"role": "user", "content": question}]
    trace = []
    for _ in range(max_steps):
        resp = ollama.chat(model=model_tag, messages=messages, tools=OLLAMA_TOOLS,
                           options={"temperature": 0, "num_ctx": 8192})
        msg = resp.message
        messages.append(msg)

        if not msg.tool_calls:
            return {"answer": msg.content, "tool_calls": trace}

        for call in msg.tool_calls:
            name, args = call.function.name, dict(call.function.arguments)
            result = await run_tool(name, args)
            trace.append({"tool": name, "args": args, "result": result})
            if verbose:
                print(f"  -> {name}({args})")
            messages.append({"role": "tool", "content": json.dumps(result), "tool_name": name})

    return {"answer": "Sorry, I could not complete this request.", "tool_calls": trace}

