import uuid
from typing import TypedDict
from langgraph.graph import StateGraph, START, END
from langgraph.types import interrupt, Command
from langgraph.checkpoint.memory import InMemorySaver

class AssistantState(TypedDict, total=False):
    question: str
    route: str
    answer: str
    tool_calls: list
    ticket: dict
    approved: bool
    review: dict

ROUTES = ["hr_policy", "it_policy", "account", "it_ticket", "out_of_scope"]

async def tool_agent(question, tool_names, system_prompt, max_steps=5):
    """Same tool-calling loop as Step 7, but with its own prompt and only its own tools."""
    tools = [t for t in OLLAMA_TOOLS if t["function"]["name"] in tool_names]
    messages = [{"role": "system", "content": system_prompt}, {"role": "user", "content": question}]
    trace = []
    for _ in range(max_steps):
        msg = ollama.chat(model=model_tag, messages=messages, tools=tools,
                          options={"temperature": 0, "num_ctx": 8192}).message
        messages.append(msg)
        if not msg.tool_calls:
            return msg.content, trace
        for call in msg.tool_calls:
            name, args = call.function.name, dict(call.function.arguments)
            if name not in tool_names:                      # agent may only use its own tools
                result = {"error": f"Tool {name} is not available to this agent."}
            else:
                result = await run_tool(name, args)         # access rule from Step 7
            trace.append({"tool": name, "args": args, "result": result})
            messages.append({"role": "tool", "content": json.dumps(result), "tool_name": name})
    return "Sorry, I could not complete this request.", trace

BASE_RULES = (f"Today is {date.today().isoformat()}. The user is employee {CURRENT_USER}. "
              "Never reveal information about other employees. If you cannot find the answer, say so. Do not guess.")

# ---- Router agent ----
async def router_node(state: AssistantState):
    resp = ollama.chat(
        model=model_tag,
        messages=[{"role": "system", "content":
                   "Classify the employee's message into exactly one route:\n"
                   "- hr_policy: questions about HR rules (leave rules, work from home, travel, expenses, code of conduct)\n"
                   "- it_policy: questions about IT rules (access, passwords, MFA, accounts, security)\n"
                   "- account: questions about the user's OWN data (my leave balance, my join date, working days between dates, can I carry over my leave)\n"
                   "- it_ticket: the user wants something done by IT (request access, software, hardware, unlock account)\n"
                   "- out_of_scope: anything else\n"
                   "Reply in JSON."},
                  {"role": "user", "content": state["question"]}],
        format={"type": "object", "properties": {"route": {"type": "string", "enum": ROUTES}},
                "required": ["route"]},
        options={"temperature": 0})
    route = json.loads(resp.message.content).get("route", "out_of_scope")
    return {"route": route if route in ROUTES else "out_of_scope"}

# ---- Specialist agents ----
async def hr_agent(state: AssistantState):
    answer, trace = await tool_agent(state["question"], {"search_policies"},
        "You are the HR policy agent. Always call search_policies, then answer only from its results "
        "and cite the source. " + BASE_RULES)
    return {"answer": answer, "tool_calls": trace}

async def it_agent(state: AssistantState):
    answer, trace = await tool_agent(state["question"], {"search_policies"},
        "You are the IT policy agent. Always call search_policies, then answer only from its results "
        "and cite the source. " + BASE_RULES)
    return {"answer": answer, "tool_calls": trace}

async def account_agent(state: AssistantState):
    answer, trace = await tool_agent(state["question"],
        {"get_leave_balance", "get_join_date", "calculate_working_days", "search_policies"},
        "You are the account agent. Use get_leave_balance, get_join_date and calculate_working_days for the "
        "user's own data. If the question also depends on a policy rule (for example carry-over), call "
        "search_policies as well and combine both. " + BASE_RULES)
    return {"answer": answer, "tool_calls": trace}

# ---- Reviewer agent: checks every specialist answer ----
async def reviewer(state: AssistantState):
    evidence = json.dumps([t["result"] for t in state.get("tool_calls", [])])[:6000]
    resp = ollama.chat(
        model=model_tag,
        messages=[{"role": "system", "content":
                   "You are a strict reviewer. Check whether the ANSWER is fully supported by the EVIDENCE "
                   "(tool results). It must not add facts that are not in the evidence, and must not reveal "
                   "another employee's data. Reply in JSON."},
                  {"role": "user", "content":
                   f"QUESTION: {state['question']}\n\nEVIDENCE: {evidence}\n\nANSWER: {state['answer']}"}],
        format={"type": "object",
                "properties": {"supported": {"type": "boolean"}, "reason": {"type": "string"}},
                "required": ["supported", "reason"]},
        options={"temperature": 0})
    verdict = json.loads(resp.message.content)
    if verdict.get("supported"):
        return {"review": verdict}
    return {"review": verdict,
            "answer": "I couldn't confirm this from the company documents or your records. "
                      "Please check with HR or the IT service desk."}

# ---- Ticket agent + human approval ----
async def ticket_draft(state: AssistantState):
    resp = ollama.chat(
        model=model_tag,
        messages=[{"role": "system", "content":
                   "Turn the employee's IT request into a ticket. category must be one of Access, Software, "
                   "Hardware, Account. description is one short sentence. Reply in JSON."},
                  {"role": "user", "content": state["question"]}],
        format={"type": "object",
                "properties": {"category": {"type": "string", "enum": ["Access", "Software", "Hardware", "Account"]},
                               "description": {"type": "string"}},
                "required": ["category", "description"]},
        options={"temperature": 0})
    return {"ticket": json.loads(resp.message.content)}

def approval(state: AssistantState):
    """Human-in-the-loop: the graph pauses here until a person approves or rejects."""
    decision = interrupt({"ticket": state["ticket"]})
    return {"approved": str(decision).strip().lower() in ("approve", "y", "yes")}

async def create_ticket(state: AssistantState):
    t = state["ticket"]
    result = await mcp_call("create_it_ticket", {"employee_id": CURRENT_USER,
                                                 "category": t["category"], "description": t["description"]})
    if "ticket_id" in result:
        answer = f"Your {result['category']} ticket #{result['ticket_id']} has been created (status: {result['status']})."
    else:
        answer = f"The ticket could not be created: {result}"
    return {"answer": answer, "tool_calls": [{"tool": "create_it_ticket", "args": t, "result": result}]}

def ticket_rejected(state: AssistantState):
    return {"answer": "Your ticket request was not approved, so no ticket was created.", "tool_calls": []}

def out_of_scope(state: AssistantState):
    return {"answer": "I can only help with Brightwave HR and IT policies, your leave and join details, "
                      "and IT requests.", "tool_calls": []}

builder = StateGraph(AssistantState)
builder.add_node("router", router_node)
builder.add_node("hr_agent", hr_agent)
builder.add_node("it_agent", it_agent)
builder.add_node("account_agent", account_agent)
builder.add_node("reviewer", reviewer)
builder.add_node("ticket_draft", ticket_draft)
builder.add_node("approval", approval)
builder.add_node("create_ticket", create_ticket)
builder.add_node("ticket_rejected", ticket_rejected)
builder.add_node("out_of_scope", out_of_scope)

builder.add_edge(START, "router")
builder.add_conditional_edges("router", lambda s: s["route"], {
    "hr_policy": "hr_agent", "it_policy": "it_agent", "account": "account_agent",
    "it_ticket": "ticket_draft", "out_of_scope": "out_of_scope"})

for node in ["hr_agent", "it_agent", "account_agent"]:
    builder.add_edge(node, "reviewer")              # specialist answers go through the reviewer
builder.add_edge("reviewer", END)

builder.add_edge("ticket_draft", "approval")
builder.add_conditional_edges("approval", lambda s: "create_ticket" if s["approved"] else "ticket_rejected")
for node in ["create_ticket", "ticket_rejected", "out_of_scope"]:
    builder.add_edge(node, END)

graph = builder.compile(checkpointer=InMemorySaver())   # checkpointer = lets the graph pause and resume
print("Graph ready")

async def chat(question, auto_decision=None):
    config = {"configurable": {"thread_id": str(uuid.uuid4())}}
    result = await graph.ainvoke({"question": question}, config)

    if "__interrupt__" in result:                          # paused at the approval node
        ticket = result["__interrupt__"][0].value["ticket"]
        print(f"[Approval needed] {ticket['category']} ticket: {ticket['description']}")
        decision = auto_decision or input("approve / reject: ")
        result = await graph.ainvoke(Command(resume=decision), config)   # resume from the pause

    print(f"Route: {result.get('route')}")
    for t in result.get("tool_calls", []):
        print(f"  -> {t['tool']}({t['args']})")
    if result.get("review"):
        print("Review:", result["review"])
    print("Answer:", result.get("answer"))
    return result

