from typing import Literal
from fastapi import FastAPI, HTTPException
from fastapi.testclient import TestClient
from pydantic import BaseModel, Field

app = FastAPI(title="Brightwave Policy Assistant API")

class ChatRequest(BaseModel):
    question: str = Field(min_length=1, max_length=2000)

class ApprovalRequest(BaseModel):
    thread_id: str
    decision: Literal["approve", "reject"]

def _final(result):
    return {"status": "answered", "route": result.get("route"),
            "answer": mask_output(result.get("answer") or "") if GUARDS["output"] else result.get("answer"),
            "tools_called": [t["tool"] for t in result.get("tool_calls", [])]}

@app.get("/health")
def health():
    return {"status": "ok", "model": model_tag, "chunks_indexed": col.count()}

@app.post("/chat")
async def chat_endpoint(req: ChatRequest):
    if GUARDS["input"] and is_injection(req.question):
        return {"status": "blocked", "route": "blocked_by_input_guard", "tools_called": [],
                "answer": "Your message was blocked because it looks like an attempt to override the assistant's rules."}
    thread_id = str(uuid.uuid4())
    config = {"configurable": {"thread_id": thread_id}}
    result = await graph.ainvoke({"question": req.question}, config)
    if "__interrupt__" in result:                       # ticket waiting for a human
        return {"status": "pending_approval", "thread_id": thread_id,
                "ticket": result["__interrupt__"][0].value["ticket"]}
    return _final(result)

@app.post("/approve")
async def approve_endpoint(req: ApprovalRequest):
    config = {"configurable": {"thread_id": req.thread_id}}
    if not graph.get_state(config).next:
        raise HTTPException(status_code=404, detail="No ticket is waiting for approval with this thread_id")
    result = await graph.ainvoke(Command(resume=req.decision), config)
    return _final(result)

