async def router_node(state: AssistantState):
    resp = ollama.chat(
        model=model_tag,
        messages=[{"role": "system", "content":
                   "Classify the employee's message into exactly one route:\n"
                   "- hr_policy: questions about HR rules (leave rules, work from home, travel, expenses, code of conduct, office facilities and notices)\n"
                   "- it_policy: QUESTIONS about IT rules (how access works, password rules, MFA, security)\n"
                   "- account: questions about the user's OWN data (my leave balance, my join date, working days between dates)\n"
                   "- it_ticket: the user WANTS IT TO DO something for them (I need / please give me / request / unlock / install)\n"
                   "- out_of_scope: anything else\n\n"
                   "Examples:\n"
                   "'How long does admin access take to approve?' -> it_policy\n"
                   "'I need VPN access for a project' -> it_ticket\n"
                   "'Please give me access to the CRM' -> it_ticket\n"
                   "'My account is locked, please unlock it' -> it_ticket\n"
                   "'What is the minimum password length?' -> it_policy\n"
                   "'How many leave days do I have left?' -> account\n"
                   "'How many sick days do employees get?' -> hr_policy\n"
                   "Reply in JSON."},
                  {"role": "user", "content": state["question"]}],
        format={"type": "object", "properties": {"route": {"type": "string", "enum": ROUTES}},
                "required": ["route"]},
        options={"temperature": 0})
    route = json.loads(resp.message.content).get("route", "out_of_scope")
    return {"route": route if route in ROUTES else "out_of_scope"}

